import os
import json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
sessions_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

with open(sessions_file, 'r') as f:
    lines = f.readlines()

# Extract text content from messages
text_content = []
for line in lines:
    try:
        msg = json.loads(line)
        if 'message' in msg:
            data = msg['message']
            if 'content' in data:
                for item in data['content']:
                    if item.get('type') == 'text':
                        text_content.append(item.get('text', ''))
    except:
        pass

# Join and search for demo-related text
full_text = '\n'.join(text_content)
print("Full text content:")
print(full_text)

